def _tie_to_scenario(text: str, activity: str, when: str, contextual_tail: str | None = None) -> str:
    """Keep each follow-up grounded in its preceding user request."""
    if activity not in text:
        text += " " + (contextual_tail or f"Для этого выбери время, чтобы {activity} {when}.")
    return text


def _clean_repeated_time_preposition(text: str) -> str:
    """Avoid doubled prepositions when a prompt template already supplies one."""
    for repeated, natural in (
        ("на на каникулах", "на каникулах"),
        ("в в выходной", "в выходной"),
        ("в в субботу", "в субботу"),
        ("после после занятий", "после занятий"),
        ("после после работы", "после работы"),
    ):
        text = text.replace(repeated, natural)
    return text


